'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { syncDsh, inspectDsh, previewDsh } = require('../lib/dsh-config');

// A small fixture parser for the JSON flow subset generated by this module.
// Production uses the Harness installation's existing official js-yaml package.
const parserSource = `exports.Type = class { constructor(name,options){this.options=options;} };
exports.JSON_SCHEMA = {extend(){return this;}};
exports.load = text => {
 const clean=text.split('\\n').filter(x=>x.trim() && !x.trim().startsWith('#')).join('\\n');
 if(!clean) return undefined;
 if(clean.startsWith('[')) return JSON.parse(clean);
 return clean.split('\\n').map(line=>{
  if(!line.startsWith('- ')) throw new Error('bad mapping');
  return JSON.parse(line.slice(2).replace(/!!js ("(?:[^"\\\\]|\\\\.)*")/g,(_,v)=>JSON.stringify({__jsExpr:JSON.parse(v)})));
 });
};`;
const ADAPTER = '@deepseek-ai/dsh-llm-pi-ai';
const TOOL = '@deepseek-ai/dsh-tool-subagent';
const PRESET = '@deepseek-ai/dsh-agent-preset';

function fixture(t, original) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'mixr-dsh-'));
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  const app = path.join(home, 'installed-app');
  fs.mkdirSync(path.join(app, 'dsh', 'node_modules', 'js-yaml'), { recursive: true });
  fs.writeFileSync(path.join(app, 'package.json'), '{}');
  fs.writeFileSync(path.join(app, 'dsh', 'package.json'), '{}');
  fs.writeFileSync(path.join(app, 'dsh', 'node_modules', 'js-yaml', 'index.js'), parserSource);
  const dir = path.join(app, 'dsh', 'node_modules', '@deepseek-ai', 'dsh-web-app', 'presets');
  fs.mkdirSync(dir, { recursive: true });
  for (const id of ['standard', 'ptc', 'cordis']) fs.writeFileSync(path.join(dir, id + '.patch.yml'), JSON.stringify([
    { insert: [{ id: 'preset-' + id, name: PRESET, config: { id, order: 4, name: id, plugins: [
      { id: 'persona', name: 'persona', config: { text: 'preserve ' + id } },
      { id: 'dynamic', name: 'dynamic', disabled: { __jsExpr: 'throw new Error("must not execute")' } },
      { id: 'delegation', name: 'cordis:group', group: true, config: [
        { id: 'tool-subagent', name: TOOL, config: { provider: 'spawn', toolName: 'subagent', maxDepth: 7, agentOptions: { maxTokens: 42, reasoningEffort: 'high' } } },
        { id: 'tool-subagent-fork', name: TOOL, config: { provider: 'fork', toolName: 'subagent_fork' } },
      ] },
    ] } }] },
  ]));
  const file = path.join(home, '.dsh', 'profiles', 'desktop', 'cordis.patch.yml');
  if (original !== undefined) { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, original); }
  const options = { home, env: { MIXR_DSH_APP: app }, routerURL: 'http://127.0.0.1:8787',
    models: [{ id: 'mixr-dsh-main', name: 'Main', contextWindow: 262144, maxTokens: 32768, input: ['text', 'image'], reasoning: true }, { id: 'mixr-dsh-haiku', reasoning: false }],
    defaultModel: 'mixr-dsh-main', defaultSubagent: 'mixr-dsh-haiku', reasoningEffort: 'high' };
  return { home, app, file, options, yaml: require(path.join(app, 'dsh', 'node_modules', 'js-yaml')) };
}
function patches(f) { return f.yaml.load(fs.readFileSync(f.file, 'utf8')); }
function strip(text) { return text.replace(/# BEGIN MIXROUTER DSH MANAGED v1\n[\s\S]*?# END MIXROUTER DSH MANAGED v1\n/, ''); }
function evaluateAdapter(f, rows) {
  const expression = rows.findLast(r => r.id === 'llm-pi-ai').config.__jsExpr;
  // Evaluate only our generated expression, never user-supplied expression nodes.
  return new Function('baseUrl', 'process', 'return ' + expression)(
    require('node:url').pathToFileURL(path.join(f.app, 'dsh', 'package.json')).href,
    { ...process, getBuiltinModule: name => require(name) });
}
const original = '# exact existing bytes / user comments\r\n' + [
  { id: 'llm-pi-ai', name: ADAPTER, config: { customAdapterField: 'keep', providers: { existing: { api: 'openai-responses', baseURL: 'https://existing.invalid/v1', apiKeyEnv: 'ORIGINAL_KEY', models: [{ id: 'old' }] } } } },
  { id: 'agent-default-model', config: { provider: 'existing', model: 'old', unrelated: 3 } },
  { id: 'subagent-model-selection-settings', config: { enabled: false, allowedModels: [{ provider: 'existing', model: 'old' }], untouched: true } },
  { id: 'unrelated', config: { apiKey: 'test-secret-that-must-stay-out-of-managed-block' } },
].map(row => '- ' + JSON.stringify(row)).join('\r\n') + '\r\n# final comment\r\n';

test('first sync creates mode 0600 config, managed provider and distinct default child route', t => {
  const f = fixture(t);
  const out = syncDsh(f.options);
  assert.equal(out.installed, true); assert.equal(out.changed, true); assert.equal(out.backup_path, null);
  assert.equal(out.routed, true); assert.equal(out.provider, 'mixrouter');
  assert.equal(fs.statSync(f.file).mode & 0o777, 0o600);
  const rows = patches(f); const provider = evaluateAdapter(f, rows).providers.mixrouter;
  assert.equal(provider.api, 'openai-responses'); assert.equal(provider.baseURL, 'http://127.0.0.1:8787/dsh/v1');
  assert.deepEqual(provider.headers, { Authorization: 'Bearer mixrouter-local' });
  assert.equal(provider.apiKeyEnv, undefined);
  assert.equal(rows.find(r => r.id === 'agent-default-model').config.model, 'mixr-dsh-main');
  assert.deepEqual(rows.find(r => r.id === 'subagent-model-selection-settings').config.allowedModels,
    [{ provider: 'mixrouter', model: 'mixr-dsh-main' }, { provider: 'mixrouter', model: 'mixr-dsh-haiku' }]);
  for (const id of ['standard', 'ptc', 'cordis']) {
    const config = rows.find(r => r.id === 'preset-' + id).config;
    assert.equal(config.order, 4); assert.equal(config.plugins[0].config.text, 'preserve ' + id);
    assert.equal(config.plugins[1].disabled.__jsExpr, 'throw new Error("must not execute")');
    const children = config.plugins[2].config;
    assert.deepEqual(children[0].config.agentOptions, { maxTokens: 42, provider: 'mixrouter', model: 'mixr-dsh-haiku' });
    assert.equal(children[0].config.maxDepth, 7); assert.equal(children[0].config.modelSelectionSettings, true);
    assert.equal(children[1].config.provider, 'fork'); assert.equal(children[1].config.agentOptions, undefined);
  }
});

test('preserves original bytes/comments/config/providers and never serializes old secrets in owned block', t => {
  const f = fixture(t, original); const out = syncDsh(f.options); const text = fs.readFileSync(f.file, 'utf8');
  assert.equal(strip(text), original);
  assert.equal(fs.readFileSync(out.backup_path, 'utf8'), original);
  assert.equal(fs.statSync(out.backup_path).mode & 0o777, 0o600);
  const rows = patches(f); const c = evaluateAdapter(f, rows);
  assert.equal(c.customAdapterField, 'keep'); assert.equal(c.providers.existing.apiKeyEnv, 'ORIGINAL_KEY');
  assert.equal(rows.findLast(r => r.id === 'agent-default-model').config.unrelated, 3);
  assert.equal(rows.findLast(r => r.id === 'subagent-model-selection-settings').config.untouched, true);
  assert.ok(!text.slice(text.indexOf('# BEGIN MIXROUTER')).includes('test-secret-that-must-stay-out-of-managed-block'));
  assert.ok(!JSON.stringify(out).includes('test-secret'));
});

test('repeat sync is no-op; model update replaces one block and whitelist exactly', t => {
  const f = fixture(t, original); syncDsh(f.options); const first = fs.readFileSync(f.file, 'utf8');
  assert.equal(syncDsh(f.options).changed, false); assert.equal(fs.readFileSync(f.file, 'utf8'), first);
  const next = { ...f.options, models: [{ id: 'mixr-dsh-sonnet' }], defaultModel: 'mixr-dsh-sonnet', defaultSubagent: 'mixr-dsh-sonnet', reasoningEffort: undefined };
  assert.equal(inspectDsh(next).status, 'out_of_sync');
  const out = syncDsh(next); assert.equal(out.changed, true);
  const text = fs.readFileSync(f.file, 'utf8'); assert.equal(strip(text), original);
  assert.equal((text.match(/^# BEGIN MIXROUTER/gm) || []).length, 1);
  assert.deepEqual(patches(f).findLast(r => r.id === 'subagent-model-selection-settings').config.allowedModels,
    [{ provider: 'mixrouter', model: 'mixr-dsh-sonnet' }]);
  assert.equal(out.model, 'mixr-dsh-sonnet');
});

test('unrelated custom preset is retained and user standard preset fields/tools retained', t => {
  const custom = { id: 'preset-custom', name: PRESET, config: { id: 'custom', plugins: [{ name: 'my-tool' }] } };
  const standard = { id: 'preset-standard', name: PRESET, config: { id: 'standard', description: 'user revision', plugins: [
    { name: 'custom-tool', config: { exact: true } }, { name: TOOL, config: { provider: 'spawn', toolName: 'subagent', allowedAgentPresets: ['custom'] } },
  ] } };
  const source = original + '- ' + JSON.stringify({ insert: [custom] }) + '\n- ' + JSON.stringify(standard) + '\n';
  const f = fixture(t, source); syncDsh(f.options); assert.equal(strip(fs.readFileSync(f.file, 'utf8')), source);
  const config = patches(f).findLast(r => r.id === 'preset-standard').config;
  assert.equal(config.description, 'user revision'); assert.deepEqual(config.plugins[0], standard.config.plugins[0]);
  assert.deepEqual(config.plugins[1].config.allowedAgentPresets, ['custom']);
});

test('external modification to managed block refuses overwrite and inspect reports conflict', t => {
  const f = fixture(t, original); syncDsh(f.options);
  const altered = fs.readFileSync(f.file, 'utf8').replace('Bearer mixrouter-local', 'Bearer externally-edited');
  fs.writeFileSync(f.file, altered);
  assert.equal(inspectDsh(f.options).status, 'conflict');
  assert.throws(() => syncDsh(f.options), e => e.statusCode === 409 && /外部修改/.test(e.message));
  assert.equal(fs.readFileSync(f.file, 'utf8'), altered);
});

test('altered native settings offer explicit read-only repair, while ordinary sync remains closed', t => {
  const f = fixture(t, original), options = v2(f); syncDsh(options);
  const first = fs.readFileSync(f.file, 'utf8');
  const altered = first.replace(/(- \{"id": "agent-default-model"[^\n]*"config": )\{[^\n]*\}(\}\n)/,
    '$1{"provider": "manual", "model": "manual-model", "unrelated": 3}$2');
  assert.notEqual(altered, first, 'fixture changes only the native main model row');
  fs.writeFileSync(f.file, altered);
  const names = fs.readdirSync(path.dirname(f.file));
  const inspected = inspectDsh(options);
  assert.equal(inspected.status, 'conflict'); assert.equal(inspected.repair_available, true);
  assert.equal(inspected.main_provider, 'manual'); assert.equal(inspected.model, 'manual-model');
  assert.throws(() => previewDsh(options), { statusCode: 409 });
  assert.throws(() => syncDsh(options), { statusCode: 409 });
  const checked = previewDsh({ ...options, repair: true });
  assert.equal(checked.repair_mode, true); assert.match(checked.profile_revision, /^[a-f0-9]{64}$/);
  assert.deepEqual(checked.main_before, { provider: 'manual', model: 'manual-model' });
  assert.deepEqual(checked.main_after, { provider: 'mixrouter', model: 'mixr-dsh-main' });
  assert.equal(fs.readFileSync(f.file, 'utf8'), altered);
  assert.deepEqual(fs.readdirSync(path.dirname(f.file)), names, 'inspect and repair preview create no backup');
  assert.throws(() => syncDsh({ ...options, repair: true }), { statusCode: 409 }, 'repair requires the exact previewed profile hash');
  const result = syncDsh({ ...options, repair: true, expectedProfileRevision: checked.profile_revision });
  assert.equal(result.changed, true); assert.equal(result.status, 'configured');
  assert.equal(fs.readFileSync(result.backup_path, 'utf8'), altered);
  assert.equal(strip(fs.readFileSync(f.file, 'utf8')), original);
  assert.deepEqual(patches(f).findLast(r => r.id === 'agent-default-model').config,
    { provider: 'mixrouter', model: 'mixr-dsh-main', unrelated: 3 });
  assert.equal(syncDsh(options).changed, false);
});

test('format-only checksum drift can be repaired, but provider expressions and extra rows cannot', t => {
  const f = fixture(t, original), options = v2(f); syncDsh(options);
  const first = fs.readFileSync(f.file, 'utf8');
  const spaced = first.replace(/^# END MIXROUTER DSH MANAGED v1$/m, '\n# END MIXROUTER DSH MANAGED v1');
  fs.writeFileSync(f.file, spaced);
  assert.equal(inspectDsh(options).repair_available, true);
  const checked = previewDsh({ ...options, repair: true });
  assert.equal(checked.repair_mode, true);
  assert.equal(fs.readFileSync(f.file, 'utf8'), spaced);
  for (const altered of [
    first.replace('Bearer mixrouter-local', 'Bearer externally-edited'),
    first.replace(/^# END MIXROUTER DSH MANAGED v1$/m, '- {"id":"unrelated-new","name":"plugin","config":{}}\n# END MIXROUTER DSH MANAGED v1'),
    first.replace('# spec: ', '# spec-invalid: '),
    first.replace(/^# BEGIN MIXROUTER DSH MANAGED v1$/m, '# BEGIN MIXROUTER DSH MANAGED changed'),
  ]) {
    fs.writeFileSync(f.file, altered);
    assert.equal(inspectDsh(options).repair_available, false);
    assert.throws(() => previewDsh({ ...options, repair: true }), { statusCode: 409 });
    assert.throws(() => syncDsh({ ...options, repair: true, expectedProfileRevision: require('node:crypto').createHash('sha256').update(altered).digest('hex') }), { statusCode: 409 });
    assert.equal(fs.readFileSync(f.file, 'utf8'), altered);
  }
});

test('repair rejects profile changes after preview before creating a backup or writing', t => {
  const f = fixture(t, original), options = v2(f); syncDsh(options);
  const altered = fs.readFileSync(f.file, 'utf8').replace(/^# END MIXROUTER DSH MANAGED v1$/m, '\n# END MIXROUTER DSH MANAGED v1');
  fs.writeFileSync(f.file, altered);
  const checked = previewDsh({ ...options, repair: true });
  const later = '# another settings change\n' + altered; fs.writeFileSync(f.file, later);
  const names = fs.readdirSync(path.dirname(f.file));
  assert.throws(() => syncDsh({ ...options, repair: true, expectedProfileRevision: checked.profile_revision }),
    e => e.statusCode === 409 && /预览后已变化/.test(e.message));
  assert.equal(fs.readFileSync(f.file, 'utf8'), later);
  assert.deepEqual(fs.readdirSync(path.dirname(f.file)), names);
});

test('external non-managed edits are preserved on resync and later model overrides refuse misleading success', t => {
  const f = fixture(t, original); syncDsh(f.options);
  const edited = fs.readFileSync(f.file, 'utf8').replace('"customAdapterField":"keep"', '"customAdapterField":"externally changed"');
  fs.writeFileSync(f.file, edited); syncDsh(f.options);
  assert.equal(evaluateAdapter(f, patches(f)).customAdapterField, 'externally changed');
  assert.equal(strip(fs.readFileSync(f.file, 'utf8')), original.replace('"customAdapterField":"keep"', '"customAdapterField":"externally changed"'));
  const tail = '- {"id":"agent-default-model","config":{"provider":"user","model":"other"}}\n';
  fs.appendFileSync(f.file, tail);
  assert.throws(() => syncDsh(f.options), /托管段之后/);
});

test('invalid configuration and owned ID collision refuse before any writes', t => {
  const f = fixture(t, original);
  for (const override of [
    { models: [] }, { models: [{ id: 'other' }] }, { models: [{ id: 'mixr-dsh-main' }, { id: 'mixr-dsh-main' }] },
    { defaultModel: 'mixr-dsh-absent' }, { defaultSubagent: 'mixr-dsh-absent' }, { routerURL: 'https://secret@localhost/v1' },
    { routerURL: 'http://localhost/?token=secret' }, { models: [{ id: 'mixr-dsh-main', contextWindow: 0 }] },
    { models: [{ id: 'mixr-dsh-main', apiKey: 'secret' }] }, { models: [{ id: 'mixr-dsh-main', input: [] }] },
  ]) assert.throws(() => syncDsh({ ...f.options, ...override }));
  assert.equal(fs.readFileSync(f.file, 'utf8'), original);
  const collision = '- ' + JSON.stringify({ id: 'llm-pi-ai', config: { providers: { mixrouter: { apiKey: 'secret' } } } }) + '\n';
  fs.writeFileSync(f.file, collision); assert.throws(() => syncDsh(f.options), /已占用/);
  assert.equal(fs.readFileSync(f.file, 'utf8'), collision);
});

test('old target expressions are never executed; symbolic configs and incompatible root rejected', t => {
  const f = fixture(t, '- {"id":"llm-pi-ai","config":!!js "process.exit(88)"}\n');
  assert.throws(() => syncDsh(f.options), /动态表达式/);
  fs.writeFileSync(f.file, '[]\n'); assert.throws(() => syncDsh(f.options), /flow-style/);
  fs.unlinkSync(f.file); const target = path.join(f.home, 'other'); fs.writeFileSync(target, original); fs.symlinkSync(target, f.file);
  assert.throws(() => syncDsh(f.options), /安全读取/); assert.equal(fs.readFileSync(target, 'utf8'), original);
});

test('installed Harness loader/schema and pi-ai SDK accept the managed integration offline', {
  skip: !process.env.MIXR_DSH_TEST_APP,
}, async t => {
  const { pathToFileURL } = require('node:url');
  let app = process.env.MIXR_DSH_TEST_APP;
  if (app.endsWith('.app')) app = path.join(app, 'Contents', 'Resources', 'app');
  const root = path.join(app, 'dsh', 'node_modules');
  const actual = async relative => import(pathToFileURL(path.join(root, relative)).href);
  const { applyEntryPatches, entryListSchema } = await actual('@deepseek-ai/cordis-plugin-include/lib/index.js');
  const { Config, apply } = await actual('@deepseek-ai/dsh-llm-pi-ai/lib/index.js');
  const yaml = require(require('node:module').createRequire(path.join(app, 'dsh', 'package.json')).resolve('js-yaml'));
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'mixr-dsh-real-'));
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  const file = path.join(home, '.dsh', 'profiles', 'desktop', 'cordis.patch.yml');
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, original);
  const options = { home, env: { MIXR_DSH_APP: app }, routerURL: 'http://127.0.0.1:8787',
    models: [{ id: 'mixr-dsh-main', input: ['text', 'image'], reasoning: true }, { id: 'mixr-dsh-sonnet', reasoning: true }],
    defaultModel: 'mixr-dsh-main', defaultSubagent: 'mixr-dsh-sonnet', reasoningEffort: 'max' };
  syncDsh(options);
  const parseActual = text => yaml.load(text, { schema: entryListSchema });
  const templates = ['standard', 'ptc', 'cordis'].flatMap(id => parseActual(fs.readFileSync(path.join(root, '@deepseek-ai', 'dsh-web-app', 'presets', id + '.patch.yml'), 'utf8')));
  const base = [{ id: 'llm-pi-ai', name: ADAPTER, config: {} },
    { id: 'agent-default-model', name: '@deepseek-ai/dsh-agent-default-model', config: {} },
    { id: 'subagent-model-selection-settings', name: '@deepseek-ai/dsh-tool-subagent/model-selection-settings', config: {} }];
  const warnings = [];
  const result = applyEntryPatches(base, [...templates, ...parseActual(fs.readFileSync(file, 'utf8'))], message => warnings.push(message));
  assert.ok(!warnings.some(x => /name mismatch/.test(x)));
  const adapterEntry = result.find(r => r.id === 'llm-pi-ai');
  const providerConfig = new Function('baseUrl', 'return ' + adapterEntry.config.__jsExpr)(pathToFileURL(path.join(app, 'dsh', 'package.json')).href);
  assert.equal(providerConfig.customAdapterField, 'keep');
  assert.equal(providerConfig.providers.existing.apiKeyEnv, 'ORIGINAL_KEY');
  const parsed = Config({ providers: { mixrouter: providerConfig.providers.mixrouter } });
  assert.equal(parsed.providers.get().mixrouter.models[0].reasoningEfforts.max, 'max');
  let realAdapter;
  apply({ fiber: { entry: { options: { id: 'llm-pi-ai' } } }, inject() {}, on() {}, get() {},
    llm: { registerConfigurableProviders() { return { replace() {} }; }, registerModelDiscovery() {},
      registerAdapter(routes, adapter) { assert.deepEqual(routes, ['mixrouter']); realAdapter = adapter; return { replace() {} }; } },
    logger: { warn() {}, error() {} } }, parsed);
  const resolved = await realAdapter.resolveModel('mixrouter', 'mixr-dsh-main');
  assert.ok(resolved.reasoning.efforts.some(e => e.id === 'max'));
  assert.deepEqual(resolved.inputModalities, ['text', 'image']);
  for (const id of ['standard', 'ptc', 'cordis']) {
    const entry = result.find(r => r.id === 'preset-' + id);
    const template = templates.flatMap(p => p.insert || []).find(r => r.id === 'preset-' + id);
    const expected = structuredClone(template.config);
    const walk = list => { for (const r of list) {
      if (r.name === TOOL && r.config?.provider === 'spawn') {
        r.config = { ...r.config, modelSelectionSettings: true, agentOptions: { ...r.config.agentOptions, provider: 'mixrouter', model: 'mixr-dsh-sonnet' } };
        delete r.config.agentOptions.reasoningEffort;
      }
      if (r.group && Array.isArray(r.config)) walk(r.config);
    } };
    walk(expected.plugins);
    assert.deepEqual(entry.config, expected);
  }
  const { streamSimple } = await actual('@earendil-works/pi-ai/dist/api/openai-responses.js');
  let requests = 0;
  const model = { id: 'mixr-dsh-main', name: 'Main', api: 'openai-responses', provider: 'mixrouter',
    baseUrl: 'http://local-fixture.invalid/dsh/v1', reasoning: false, input: ['text'], contextWindow: 262144, maxTokens: 32768,
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 } };
  const context = { messages: [{ role: 'user', content: [{ type: 'text', text: 'fixture' }], timestamp: 0 }] };
  const chunks = [];
  const stream = streamSimple(model, context, { headers: { Authorization: 'Bearer mixrouter-local' }, maxRetries: 0,
    fetch: async (url, init) => {
      requests++;
      assert.match(String(url), /\/dsh\/v1\/responses$/);
      assert.equal(new Headers(init.headers).get('authorization'), 'Bearer mixrouter-local');
      const payload = JSON.parse(init.body); assert.equal(payload.stream, true); assert.equal(payload.model, model.id);
      const response = { id: 'fixture-response', object: 'response', status: 'completed', model: model.id,
        output: [], usage: { input_tokens: 1, output_tokens: 0, total_tokens: 1 } };
      return new Response('event: response.completed\ndata: ' + JSON.stringify({ type: 'response.completed', response }) + '\n\n',
        { headers: { 'content-type': 'text/event-stream' } });
    } });
  for await (const chunk of stream) chunks.push(chunk);
  assert.equal(requests, 1);
  assert.ok(!chunks.some(c => c.type === 'error'), JSON.stringify(chunks.filter(c => c.type === 'error')));
  assert.ok(chunks.some(c => c.type === 'done'));
});

test('redirected config path is respected and absent installation is reported', t => {
  const f = fixture(t); const redirected = path.join(f.home, 'redirected.yml');
  const opts = { ...f.options, env: { ...f.options.env, MIXR_DSH_CONFIG: redirected } };
  assert.equal(syncDsh(opts).config_path, redirected); assert.equal(fs.existsSync(f.file), false);
  const absent = { ...opts, env: { ...opts.env, MIXR_DSH_APP: path.join(f.home, 'absent') } };
  assert.equal(inspectDsh(absent).installed, false); assert.throws(() => syncDsh(absent), /未找到/);
});

function v2(f, patch = {}) {
  const { defaultSubagent, reasoningEffort, ...options } = f.options;
  return { ...options, models: [{ id: 'mixr-dsh-main' }, { id: 'mixr-dsh-haiku', input: ['text'],
    contextWindow: 128000, maxTokens: 8192, reasoningEfforts: { off: null, low: 'light', high: 'deep' } }],
    policyOwner: 'mixrouter', subagentPolicy: { enabled: true,
      allowedModels: [{ provider: 'mixrouter', model: 'mixr-dsh-haiku' }], defaultMode: 'slot',
      defaultModel: 'mixr-dsh-haiku', maxDepth: 1, maxActiveSubagents: 4 }, ...patch };
}
function spawnConfig(rows, id = 'standard') { return rows.findLast(r => r.id === 'preset-' + id).config.plugins[2].config[0].config; }
function managedRows(f) {
  const body = fs.readFileSync(f.file, 'utf8').match(/^# BEGIN MIXROUTER DSH MANAGED v1\n([\s\S]*?)^# END MIXROUTER DSH MANAGED v1/m)[1];
  return f.yaml.load(body);
}

