test('installed Harness accepts v2 exact routes, limits, true inheritance and native handoff offline', {
  skip: !process.env.MIXR_DSH_TEST_APP,
}, async t => {
  const { pathToFileURL } = require('node:url');
  let app = process.env.MIXR_DSH_TEST_APP;
  if (app.endsWith('.app')) app = path.join(app, 'Contents', 'Resources', 'app');
  const root = path.join(app, 'dsh', 'node_modules');
  const actual = relative => import(pathToFileURL(path.join(root, relative)).href);
  const [{ applyEntryPatches, entryListSchema }, adapterModule, toolModule, selectionModule, hostModule] = await Promise.all([
    actual('@deepseek-ai/cordis-plugin-include/lib/index.js'), actual('@deepseek-ai/dsh-llm-pi-ai/lib/index.js'),
    actual('@deepseek-ai/dsh-tool-subagent/lib/index.js'), actual('@deepseek-ai/dsh-tool-subagent/lib/model-selection-settings.js'),
    actual('@deepseek-ai/dsh-subagent/lib/index.js'),
  ]);
  const yaml = require(require('node:module').createRequire(path.join(app, 'dsh', 'package.json')).resolve('js-yaml'));
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'mixr-dsh-real-v2-'));
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  const file = path.join(home, '.dsh', 'profiles', 'desktop', 'cordis.patch.yml');
  fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, original);
  const options = { home, env: { MIXR_DSH_APP: app }, routerURL: 'http://127.0.0.1:8787',
    models: [{ id: 'mixr-dsh-main' }, { id: 'mixr-dsh-worker', input: ['text'], contextWindow: 128000, maxTokens: 8192,
      reasoningEfforts: { off: null, low: 'light', high: 'deep' } }],
    defaultModel: 'mixr-dsh-main', policyOwner: 'mixrouter', subagentPolicy: { enabled: true,
      allowedModels: [{ provider: 'mixrouter', model: 'mixr-dsh-worker' }], defaultMode: 'slot',
      defaultModel: 'mixr-dsh-worker', maxDepth: 1, maxActiveSubagents: 4 } };
  const parseActual = text => yaml.load(text, { schema: entryListSchema });
  const templates = ['standard', 'ptc', 'cordis'].flatMap(id => parseActual(fs.readFileSync(path.join(root, '@deepseek-ai', 'dsh-web-app', 'presets', id + '.patch.yml'), 'utf8')));
  const base = [{ id: 'llm-pi-ai', name: ADAPTER, config: {} },
    { id: 'agent-default-model', name: '@deepseek-ai/dsh-agent-default-model', config: {} },
    { id: 'subagent-model-selection-settings', name: '@deepseek-ai/dsh-tool-subagent/model-selection-settings', config: {} },
    { id: 'subagent', name: '@deepseek-ai/dsh-subagent', config: {} }];
  const applied = () => {
    const warnings = [];
    const rows = applyEntryPatches(base, [...templates, ...parseActual(fs.readFileSync(file, 'utf8'))], text => warnings.push(text));
    assert.ok(!warnings.some(text => /name mismatch/.test(text)), warnings.join('\n'));
    return rows;
  };
  const spawnEntries = rows => {
    const entries = [];
    const walk = list => { for (const row of list) {
      if (row.name === TOOL && row.config?.provider === 'spawn') entries.push(row.config);
      if (row.group && Array.isArray(row.config)) walk(row.config);
    } };
    for (const id of ['standard', 'ptc', 'cordis']) walk(rows.find(row => row.id === 'preset-' + id).config.plugins);
    assert.equal(entries.length, 3); return entries;
  };
  syncDsh(options);
  const rows = applied();
  for (const config of spawnEntries(rows)) {
    const parsed = toolModule.Config(config);
    assert.equal(parsed.maxDepth, 1); assert.equal(parsed.modelSelectionSettings, true);
    assert.equal(parsed.agentOptions.model, 'mixr-dsh-worker'); assert.equal(parsed.agentOptions.provider, 'mixrouter');
    assert.equal(Object.hasOwn(parsed.agentOptions, 'reasoningEffort'), false);
  }
  const selection = selectionModule.SubagentModelSelectionConfig.Config(rows.find(row => row.id === 'subagent-model-selection-settings').config);
  assert.equal(selection.enabled.get(), true);
  assert.deepEqual(selection.allowedModels.get(), options.subagentPolicy.allowedModels);
  const limits = hostModule.SubagentRuntime.Config(rows.find(row => row.id === 'subagent').config);
  assert.equal(limits.maxDepth.get(), 1); assert.equal(limits.maxActiveSubagents.get(), 4);
  const adapterEntry = rows.find(row => row.id === 'llm-pi-ai');
  const config = new Function('baseUrl', 'return ' + adapterEntry.config.__jsExpr)(pathToFileURL(path.join(app, 'dsh', 'package.json')).href);
  assert.deepEqual(config.providers.mixrouter.models[1].reasoningEfforts, { off: null, low: 'light', high: 'deep' });
  let adapter;
  adapterModule.apply({ fiber: { entry: { options: { id: 'llm-pi-ai' } } }, inject() {}, on() {}, get() {},
    llm: { registerConfigurableProviders() { return { replace() {} }; }, registerModelDiscovery() {},
      registerAdapter(routes, value) { adapter = value; return { replace() {} }; } }, logger: { warn() {}, error() {} } },
    adapterModule.Config({ providers: { mixrouter: config.providers.mixrouter } }));
  const main = await adapter.resolveModel('mixrouter', 'mixr-dsh-main');
  const worker = await adapter.resolveModel('mixrouter', 'mixr-dsh-worker');
  assert.deepEqual(main.inputModalities, ['text']); assert.equal(main.reasoning, undefined);
  assert.equal(main.context.contextWindow, 262144);
  assert.deepEqual(worker.inputModalities, ['text']); assert.equal(worker.context.contextWindow, 128000);
  assert.equal(worker.defaultMaxTokens, 8192);
  assert.deepEqual(worker.reasoning.efforts.map(effort => effort.id), ['off', 'low', 'high']);
  const inherit = { ...options, subagentPolicy: { enabled: false, allowedModels: options.subagentPolicy.allowedModels,
    defaultMode: 'inherit', maxDepth: 0 } };
  syncDsh(inherit);
  for (const config of spawnEntries(applied())) {
    const parsed = toolModule.Config(config);
    assert.equal(parsed.maxDepth, 0); assert.equal(parsed.modelSelectionSettings, false);
    for (const key of ['provider', 'model', 'reasoningEffort']) assert.equal(Object.hasOwn(parsed.agentOptions, key), false);
  }
  const native = { ...inherit, policyOwner: 'harness' };
  const preview = previewDsh(native);
  assert.equal(preview.changes.native_handoff, true);
  syncDsh(native);
  const nativeRows = applied();
  assert.equal(nativeRows.find(row => row.id === 'agent-default-model').config.model, 'mixr-dsh-main');
  assert.equal(selectionModule.SubagentModelSelectionConfig.Config(nativeRows.find(row => row.id === 'subagent-model-selection-settings').config).enabled.get(), false);
  assert.equal(hostModule.SubagentRuntime.Config(nativeRows.find(row => row.id === 'subagent').config).maxActiveSubagents.get(), 4);
  assert.equal(syncDsh(native).changed, false);
});

